<script setup lang="ts">
import {defineAsyncComponent,ref,onMounted,onBeforeUnmount} from 'vue';
import {getSession,login,logout,refreshCsrf} from '../FleetAndDocuments/api';
import type {Session} from '../FleetAndDocuments/contracts';
import {request,failure} from '../Administration/api';
const AlertsApp=defineAsyncComponent(()=>import('../DocumentAlerts/AlertsApp.vue'));
import ExpirationIndicators from '../DocumentAlerts/ExpirationIndicators.vue';
const AuditApp=defineAsyncComponent(()=>import('../AdministrativeAudit/AuditApp.vue'));
const ReportsApp=defineAsyncComponent(()=>import('../AdministrativeReports/ReportsApp.vue'));
const ExpensesApp=defineAsyncComponent(()=>import('../Expenses/ExpensesApp.vue'));
import DriverTrips from './DriverTrips.vue';
import {rememberActor,offlineActor,lockLocal,forgetReadCache,captures} from '../DriverPortal/offline';
import {registerDriverPwa} from '../DriverPortal/pwa';
const BillingReview=defineAsyncComponent(()=>import('./BillingReview.vue'));
import '../Workshop/workshop.css';
import SharedNavigation from './SharedNavigation.vue';
import WorkOverview from './WorkOverview.vue';
import {useNavigation} from './useNavigation';
import {useOffice} from '../Office/context';
const officeHost=useOffice(()=>busy.value||operationLocked.value);
const navigation=useNavigation();
const section=officeHost?'dashboard':document.getElementById('system-app')?.dataset.section??'login';
const session=ref<Session|null>(null),loading=ref(true),busy=ref(false),error=ref(''),username=ref(''),password=ref('');
const operationLocked=ref(false),pwaStatus=ref('');
function acceptSession(actor:Session):void{const previous=offlineActor();if(previous&&previous.id!==actor.id){lockLocal();void forgetReadCache(previous.id).catch(()=>{});}if(section==='driver')rememberActor(actor);session.value=actor;}
function guardNavigation(event:MouseEvent):void{if(operationLocked.value&&event.target instanceof Element&&event.target.closest('a'))event.preventDefault();}
const counters=ref<{key:string;label:string;value:number;href:string}[]>([]);let generation=0;
async function report(e:unknown):Promise<void>{const problem=failure(e);error.value=problem.message;if([401,403,419].includes(problem.status)){if(section==='driver')lockLocal();session.value=null;counters.value=[];officeHost?.invalidate();}}
async function home():Promise<void>{if(!session.value)return;const result=await navigation.get(session.value);window.location.assign(result.home);}
async function signIn():Promise<void>{if(busy.value)return;busy.value=true;error.value='';try{await refreshCsrf();const actor=await login(username.value,password.value);acceptSession(actor);password.value='';const roles=actor.roles;const keepPage=(section==='alerts'&&roles.some(role=>['administrator','secretary'].includes(role)))||(['reports','audit'].includes(section)&&roles.includes('administrator'))||(section==='billing'&&roles.some(role=>['administrator','secretary'].includes(role)))||(section==='expenses'&&roles.some(role=>['administrator','secretary'].includes(role)))||(section==='driver'&&roles.some(role=>['administrator','driver'].includes(role)));if(!keepPage)await home();}catch(e){await report(e);}finally{password.value='';busy.value=false;}}
async function exit():Promise<void>{if(busy.value||operationLocked.value)return;busy.value=true;try{const actor=session.value?.id;if(section==='driver'&&actor){const pending=(await captures(actor)).filter(c=>c.status!=='sincronizado');if(pending.length&&!confirm(`Hay ${pending.length} capturas sin confirmar (incluidos errores o conflictos). Se conservarán ocultas para esta cuenta en este dispositivo; vuelve a abrir con la cuenta original y conexión para atenderlas. No es obligatorio sincronizarlas ahora. ¿Cerrar sesión?`))return;if(!navigator.onLine){error.value='Sin conexión: no se puede confirmar el cierre de sesión del servidor. Puedes cerrar la aplicación sin borrar sus datos; las capturas se conservan. Vuelve con conexión para cerrar sesión o cambiar de cuenta.';return;}await logout();}else await logout();session.value=null;counters.value=[];window.location.assign('/login');}catch(e){await report(e);}finally{busy.value=false;}}
async function load():Promise<void>{const current=++generation;loading.value=true;error.value='';try{const actor=officeHost?.context.value?.session??await getSession();if(current!==generation)return;if(officeHost)session.value=actor;else acceptSession(actor);if(section==='login'){await home();return;}if(section==='dashboard'){const data=await request<{counters:typeof counters.value}>('/dashboard');if(current===generation)counters.value=data.counters;}}catch(e){if(current===generation){if(section==='driver'&&failure(e).status===0){session.value=offlineActor();error.value=session.value?'Modo local: la identidad recordada solo permite capturar; el servidor validará la sesión al sincronizar.':'Conecta e inicia sesión para habilitar este dispositivo.';}else if(!(section==='login'&&failure(e).status===401))await report(e);}}finally{if(current===generation)loading.value=false;}}
function localChanged(event:StorageEvent):void{if(section==='driver'&&event.key==='driver-offline-active-v1'&&offlineActor()?.id!==session.value?.id){session.value=null;error.value='La sesión local cambió en otra pestaña. Las capturas pendientes se conservan para la cuenta original. Autentícate nuevamente.';}}
onMounted(()=>{void load();if(section==='driver'){void registerDriverPwa(message=>pwaStatus.value=message);window.addEventListener('storage',localChanged);}});onBeforeUnmount(()=>{generation++;window.removeEventListener('storage',localChanged);});
</script>
<template><div @click.capture="guardNavigation" :class="{'driver-mobile':section==='driver'}" class="administration-shell min-h-screen bg-blue-50 text-slate-900"><header v-if="!officeHost" class="bg-white border-b border-blue-200"><div class="max-w-7xl mx-auto p-5 flex flex-wrap justify-between gap-4"><div><p class="text-blue-800 font-semibold">Transportes Líquidos</p><h1 class="text-2xl font-bold">{{section==='dashboard'?'Panel general':section==='driver'?'Mis viajes':section==='billing'?'Facturación de transporte':section==='alerts'?'Alertas y vencimientos':section==='audit'?'Auditoría administrativa':section==='reports'?'Reportes administrativos':section==='expenses'?'Gastos administrativos y operativos':'Acceso al sistema'}}</h1></div><button v-if="session" class="btn-secondary" :disabled="busy||operationLocked" @click="exit">Cerrar sesión</button><SharedNavigation :workspace="section!=='driver'" :session="session" :disabled="busy||operationLocked"/></div></header><main class="max-w-7xl mx-auto p-4 md:p-6 space-y-5"><p v-if="loading" role="status">Consultando sesión…</p><p v-if="error" class="notice-error" role="alert">{{error}}</p><form v-if="!loading&&!session" class="panel max-w-md mx-auto space-y-4" @submit.prevent="signIn"><h2 class="text-xl font-semibold">Iniciar sesión</h2><label class="block">Usuario<input v-model="username" class="field mt-2" autocomplete="username" required :disabled="busy"></label><label class="block">Contraseña<input v-model="password" class="field mt-2" type="password" autocomplete="current-password" required :disabled="busy"></label><button class="btn-primary" :disabled="busy">{{busy?'Ingresando…':'Iniciar sesión'}}</button></form><WorkOverview v-if="!loading&&session&&section==='dashboard'" :session="session"/><section v-if="!loading&&session&&section==='dashboard'" aria-label="Resumen general" class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><a v-for="counter in counters" :key="counter.key" :href="counter.href" class="panel hover:border-blue-500"><h2 class="text-blue-800 font-semibold">{{counter.label}}</h2><p class="text-3xl font-bold mt-3">{{new Intl.NumberFormat('es-CR').format(counter.value)}}</p><span class="text-sm text-blue-700">Consultar registros →</span></a></section><p v-if="!loading&&session&&section==='dashboard'" class="text-sm text-slate-600">Conteos de registros actuales del sistema. No representan ingresos ni indicadores financieros.</p><p v-if="section==='driver'&&pwaStatus" role="status" class="notice-info">{{pwaStatus}}</p><DriverTrips v-if="section==='driver'" :session="session" @denied="report" @lock="operationLocked=$event" @session="acceptSession"/><ExpirationIndicators v-if="section==='dashboard'" :session="session"/><AlertsApp v-if="section==='alerts'" :session="session" @denied="report" @lock="operationLocked=$event"/><AuditApp v-if="section==='audit'" :session="session" @denied="report"/><ReportsApp v-if="section==='reports'" :session="session" @denied="report"/><ExpensesApp v-if="section==='expenses'" :session="session" @denied="report" @lock="operationLocked=$event" @session="acceptSession"/><BillingReview v-if="section==='billing'" :session="session" @denied="report" @lock="operationLocked=$event" @session="acceptSession"/><button v-if="error" class="btn-secondary" :disabled="busy||loading||operationLocked" @click="load">Comprobar sesión y actualizar</button></main></div></template>

<style scoped>
.driver-mobile {overflow-wrap:anywhere;}
.driver-mobile > header > div,.driver-mobile > main {min-width:0;}
.driver-mobile :deep(.field) {min-width:0;max-width:100%;box-sizing:border-box;}
</style>
